#!/usr/bin/env Rscript
source("code/01_common.R")
spec<-list(B=list(ex=c(12,13,14,16,17),res=.6),Endothelial=list(ex=c(7,11,18,20,22),res=.6),Fibroblast=list(ex=c(10,11,12,19,21,23),res=1),Myeloid=list(ex=c(5,11,19,23),res=.8))
lineage<-Sys.getenv("ROUND2_LINEAGE",unset="");if(!lineage%in%names(spec))stop("Set ROUND2_LINEAGE to one of: ",paste(names(spec),collapse=","))
s<-spec[[lineage]];out<-file.path(r2,lineage);dir.create(out,recursive=TRUE,showWarnings=FALSE);t0<-Sys.time();message("START ",lineage)
q1<-file.path(r1,lineage,paste0(lineage,"_round1_clustered.qs"));o1<-qs::qread(q1);input_n<-ncol(o1);keep<-!as.character(o1$cluster_v2_round1)%in%as.character(s$ex);excluded<-as.data.frame(table(cluster_v2_round1=as.character(o1$cluster_v2_round1[!keep])),stringsAsFactors=FALSE);names(excluded)[2]<-"n_excluded_cells";write.csv(excluded,file.path(out,"excluded_round1_clusters_and_counts.csv"),row.names=FALSE)
o<-subset(o1,cells=colnames(o1)[keep]);rm(o1);invisible(gc());stopifnot("cluster_v2_round1"%in%colnames(o[[]]),all(c("counts","data")%in%Layers(o[["RNA"]],search=NA)));DefaultAssay(o)<-"RNA"
before<-data.frame(stage="before",layer=Layers(o[["RNA"]],search=NA),cells=ncol(o));cts<-grep("^counts($|\\.)",Layers(o[["RNA"]],search=NA),value=TRUE);if(length(cts)>1)o<-JoinLayers(o,assay="RNA");if("scale.data"%in%Layers(o[["RNA"]],search=NA))LayerData(o,assay="RNA",layer="scale.data")<-NULL
o<-FindVariableFeatures(o,assay="RNA",selection.method="vst",nfeatures=3000,verbose=TRUE);o<-ScaleData(o,assay="RNA",features=VariableFeatures(o),verbose=TRUE);o<-RunPCA(o,assay="RNA",features=VariableFeatures(o),npcs=50,reduction.name="pca_round2",seed.use=20260915,verbose=TRUE);o<-harmony::RunHarmony(o,group.by.vars="orig.ident",reduction.use="pca_round2",dims.use=1:30,reduction.save="harmony_round2",verbose=TRUE);o<-FindNeighbors(o,reduction="harmony_round2",dims=1:30,graph.name=c("round2_nn","round2_snn"),verbose=TRUE);o<-FindClusters(o,graph.name="round2_snn",resolution=s$res,cluster.name="cluster_v2_round2",algorithm=1,random.seed=20260915,verbose=TRUE);o$cluster_v2_round2<-factor(as.character(o$cluster_v2_round2),levels=cluster_levels(o$cluster_v2_round2));Idents(o)<-"cluster_v2_round2";o<-RunUMAP(o,reduction="harmony_round2",dims=1:30,reduction.name="umap_round2",reduction.key="round2UMAP_",seed.use=20260915,verbose=TRUE)
after<-data.frame(stage="after",layer=Layers(o[["RNA"]],search=NA),cells=ncol(o));write.csv(bind_rows(before,after),file.path(out,"layer_audit_round2.csv"),row.names=FALSE);stopifnot("counts"%in%Layers(o[["RNA"]],search=NA),"data"%in%Layers(o[["RNA"]],search=NA))
save_pair(umap_plot(o,"cluster_v2_round2",label=TRUE),file.path(out,"01_umap_cluster_round2"));save_pair(umap_plot(o,"dataset"),file.path(out,"02_umap_dataset_round2"));save_pair(umap_plot(o,"orig.ident"),file.path(out,"03_umap_specimen_round2"),13,9);save_pair(umap_plot(o,"orig.ident",legend=FALSE),file.path(out,"03_umap_specimen_round2_nolegend"),10,8.5);save_pair(umap_plot(o,"cluster_v2_round1",label=TRUE),file.path(out,"04_umap_round1_cluster_on_round2_embedding"))
panel<-read.csv(file.path(r1,lineage,"marker_panel_used.csv"),check.names=FALSE,stringsAsFactors=FALSE);if(lineage=="Fibroblast"){add<-data.frame(marker_group="MyoFibro / SMC",gene=c("ACTA2","TAGLN","MYH11"),group_order=max(panel$group_order)+1,marker_order=max(panel$marker_order)+1:3,source_md="Fibroblast_round2_reclustering_plan_res1.0.md",present=c("ACTA2","TAGLN","MYH11")%in%rownames(o));panel<-rbind(panel,add)};panel<-panel[order(panel$marker_order),];write.csv(panel,file.path(out,"marker_panel_used_round2.csv"),row.names=FALSE);write.csv(panel[!panel$present,,drop=FALSE],file.path(out,"missing_markers_round2.csv"),row.names=FALSE);if(any(!panel$present))panel<-panel[panel$present,,drop=FALSE];dotname<-if(lineage=="Fibroblast")"05_dotplot_frozen_markers_plus_myo_smc_round2" else "05_dotplot_frozen_markers_round2";dotplot_grouped(o,panel,"cluster_v2_round2",file.path(out,dotname))
nmarkers<-write_markers(o,out,"cluster_v2_round2");audit<-write_composition(o,out,"cluster_v2_round2");map<-write_mapping(o,out,"cluster_v2_round2");decision_template(o,out,"cluster_v2_round2",map)
o$round2_lineage<-lineage;o$round2_excluded_round1_clusters<-paste(s$ex,collapse=",");o$round2_resolution<-s$res;o$round2_annotation_status<-"UNANNOTATED_MANUAL_REVIEW_REQUIRED";o@misc$round2_parameters<-list(seed=20260915,HVG=3000,PCA=50,dims="1:30",Harmony_group="orig.ident",resolution=s$res)
q2<-file.path(out,paste0(lineage,"_round2_clustered.qs"));qs::qsave(o,q2,preset="high",nthreads=16);t1<-Sys.time();summary<-data.frame(lineage=lineage,status="READY_FOR_MANUAL_ANNOTATION",input_cells=input_n,excluded_cells=sum(!keep),round2_cells=ncol(o),round2_clusters=length(unique(o$cluster_v2_round2)),resolution=s$res,n_markers=nmarkers,n_composition_warning_clusters=sum(audit$warning_single_specimen_gt50|audit$warning_single_dataset_gt70|audit$warning_very_small|audit$warning_very_few_specimens),start_utc=format(t0,tz="UTC",usetz=TRUE),end_utc=format(t1,tz="UTC",usetz=TRUE),runtime_minutes=as.numeric(difftime(t1,t0,units="mins")),stringsAsFactors=FALSE);write.csv(summary,file.path(out,paste0(lineage,"_round2_run_summary.csv")),row.names=FALSE);writeLines(c(paste0(if(lineage=="Endothelial")"ENDO" else toupper(lineage),"_ROUND2_STATUS = READY_FOR_MANUAL_ANNOTATION"),paste0("Runtime minutes: ",round(summary$runtime_minutes,2))),file.path(out,paste0(lineage,"_ROUND2_SUMMARY.md")));message("DONE ",lineage," clusters=",summary$round2_clusters)
